INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Projektabschluss immer nur eine formelle Übergabe?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst auch Dokumentation und Reflexion"}, {"text": "Ja", "correct": false, "because": "Mehr als Übergabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel des Projektabschlusses?', 3, '[{"text": "Ergebnisse sichern", "correct": true, "because": "Stellt Fertigstellung sicher"}, {"text": "Neue Projekte starten", "correct": false, "because": "Nicht primär"}, {"text": "Manuelle Kontrolle", "correct": false, "because": "Strukturierte Prozesse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aktivitäten gehören zum Projektabschluss?', 5, '[{"text": "Abschlussdokumentation", "correct": true, "because": "Erfasst Ergebnisse"}, {"text": "Lessons Learned", "correct": true, "because": "Verbessert zukünftige Projekte"}, {"text": "Neue Zielsetzung", "correct": false, "because": "Planungsphase"}, {"text": "Musikwiedergabe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Projektabschluss schließt die Übergabe ein. b) Er ersetzt die Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist andere Phase"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Projektabschluss?', 4, '[{"text": "Dokumentation", "correct": false, "because": "Sichert Nachvollziehbarkeit"}, {"text": "Stakeholder-Zufriedenheit", "correct": false, "because": "Bestätigt Erfolg"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant für Abschluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Projektabschluss immer eine Feier beinhaltet?', 2, '[{"text": "Nein", "correct": true, "because": "Feier optional, Dokumentation zentral"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe ist beim Projektabschluss entscheidend?', 3, '[{"text": "Ergebnisübergabe", "correct": true, "because": "Sichert Projektziel"}, {"text": "Neue Planung", "correct": false, "because": "Andere Phase"}, {"text": "Manuelle Prüfung", "correct": false, "because": "Strukturierte Prozesse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dokumente entstehen beim Projektabschluss?', 5, '[{"text": "Abschlussbericht", "correct": true, "because": "Dokumentiert Ergebnisse"}, {"text": "Lessons Learned", "correct": true, "because": "Erfasst Erkenntnisse"}, {"text": "Marketingpläne", "correct": false, "because": "Nicht abschlussrelevant"}, {"text": "Grafikdesigns", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Der Projektabschluss bestätigt Zielerreichung. b) Er ist nur für Kunden relevant. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) betrifft auch Team"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Projektabschluss?', 4, '[{"text": "Abschlussbericht", "correct": false, "because": "Dokumentiert Ergebnisse"}, {"text": "Stakeholder-Freigabe", "correct": false, "because": "Bestätigt Abschluss"}, {"text": "3D-Modellierung", "correct": true, "because": "Irrelevant für Abschluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Projektabschluss nur für interne Zwecke?', 2, '[{"text": "Nein", "correct": true, "because": "Betrifft Kunden und Team"}, {"text": "Ja", "correct": false, "because": "Externe Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind beim Projektabschluss typisch?', 4, '[{"text": "Ressourcenfreigabe", "correct": true, "because": "Beendet Einsatz"}, {"text": "Abschlussbesprechung", "correct": true, "because": "Reflektiert Ergebnisse"}, {"text": "Neue Zielsetzung", "correct": false, "because": "Planungsphase"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der Projektabschluss immer schnell erfolgt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Erfordert Dokumentation und Reflexion"}, {"text": "Ja", "correct": false, "because": "Zeitaufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Projektabschluss?', 3, '[{"text": "Dokumentation", "correct": true, "because": "Sichert Nachvollziehbarkeit"}, {"text": "Neue Aufgaben", "correct": false, "because": "Andere Phase"}, {"text": "Manuelle Prüfung", "correct": false, "because": "Strukturierte Prozesse"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Lessons Learned verbessern Projekte. b) Der Abschluss ignoriert Kunden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) berücksichtigt Kunden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein guter Projektabschluss?', 5, '[{"text": "Nachvollziehbarkeit", "correct": true, "because": "Dokumentation sichert"}, {"text": "Verbesserte Prozesse", "correct": true, "because": "Lessons Learned"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher Nachteil"}, {"text": "Einmalige Nutzung", "correct": false, "because": "Langfristige Wirkung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Projektabschluss unwichtig?', 3, '[{"text": "Dokumentation", "correct": false, "because": "Sichert Ergebnisse"}, {"text": "Stakeholder-Feedback", "correct": false, "because": "Bestätigt Erfolg"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Abschlussfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Projektabschluss für agile Projekte relevant ist?', 2, '[{"text": "Ja", "correct": true, "because": "Schließt Iterationen ab"}, {"text": "Nein", "correct": false, "because": "Auch in Agile nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Beinhaltet der Projektabschluss immer eine Kostenanalyse?', 3, '[{"text": "Nein", "correct": true, "because": "Optional, nicht zwingend"}, {"text": "Ja", "correct": false, "because": "Fokus auf Dokumentation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zum Projektabschluss?', 4, '[{"text": "Übergabe einer Software", "correct": true, "because": "Schließt Projekt ab"}, {"text": "Musikwiedergabe", "correct": false, "because": "Keine Projektphase"}, {"text": "Netzwerkwartung", "correct": false, "because": "Technische Aufgabe"}]');
